// 1. On récupère le titre envoyé par l'IA
const inputTrigger = $('When Executed by Another Workflow').first().json;
let recherche = (inputTrigger.titre || "").toLowerCase().trim();

// Sécurité : On enlève les guillemets ou la ponctuation que l'IA pourrait inventer
recherche = recherche.replace(/["'.,;?!]/g, "").trim();

// 2. On récupère TOUTES les BD depuis le nœud Get row(s) juste avant
const toutesLesBDs = $input.all();

// Test de sécurité : Si la base ne renvoie rien
if (toutesLesBDs.length === 0) {
  return [{ json: { message: `Erreur interne : Je n'ai pas pu lire la base de données (0 livre trouvé).` } }];
}

// 3. Recherche de la BD
const resultat = toutesLesBDs.find(item => {
  let titreBase = (item.json.titre || "").toLowerCase().trim();
  // On regarde si l'un contient l'autre (ex: "Toriko" contient "toriko")
  return titreBase.includes(recherche) || recherche.includes(titreBase);
});

// 4. On prépare la réponse
if (resultat) {
  const b = resultat.json;
  const possedes = parseInt(b.albums_possedes) || 0;
  const manquants = parseInt(b.albums_manquants) || 0;
  const lus = parseInt(b.albums_lus) || 0;

  return [{
    json: {
      message: `J'ai trouvé la série "${b.titre}". Tu possèdes ${possedes} tomes (dont ${lus} lus) et il t'en manque ${manquants}.`,
      found: true
    }
  }];
} else {
  return [{
    json: {
      message: `Désolé, je ne trouve pas de série nommée "${recherche}". (Info technique: j'ai cherché dans ${toutesLesBDs.length} livres de ta base).`,
      found: false
    }
  }];
}
